export function exerciseFor(focus, date) {
  const list = practiceCatalog[focus] || practiceCatalog['Общий импрув — пока не знаю, что проседает'];
  const day = Math.floor(Date.parse(`${date}T12:00:00Z`) / 86400000);
  const index = Number.isFinite(day) ? day : 0;
  const base = list[index % list.length];
  const variation = Math.floor(index / list.length) % 3;
  if (variation === 0) return base;
  if (variation === 1) return {title:`${base.title}: неизвестная информация`,setup:`Повтори упражнение в двух новых подходящих ситуациях. Перед действием назови, какой информации тебе не хватает. ${base.setup}`,measure:`${base.measure} Отдельно отметь, что было неизвестно до решения.`};
  return {title:`${base.title}: сравни два исхода`,setup:`Найди две похожие ситуации и повтори упражнение. ${base.setup} Сравни условия, а не только результат.`,measure:`${base.measure} Что различалось между ситуациями?`};
}
